<?php require ROOT.'/app/Core/views/notices.php'; ?>
<div class="two-col"><section class="card"><h2>Unfinished actions first</h2><?php $returnTo='/review'; require __DIR__.'/tasks.php'; ?></section><section class="card"><h2>Open lessons to reflect on</h2><?php if (!$openLessons): ?><p class="muted">No open lessons.</p><?php else: foreach ($openLessons as $l): ?><div class="simple-row"><span><strong><?= e($l['area']) ?></strong><small><?= e($l['what_happened']) ?></small><small>Action: <?= e($l['action'] ?: 'Not yet chosen') ?></small></span></div><?php endforeach; endif; ?></section></div>
<div class="two-col"><section class="card"><h2>This week’s review</h2><form class="stack" method="post" action="/review"><?= csrf_field() ?><label>What went well?<textarea name="wins" rows="3" maxlength="5000"><?= e($current['wins'] ?? '') ?></textarea></label><label>What didn’t work?<textarea name="fails" rows="3" maxlength="5000"><?= e($current['fails'] ?? '') ?></textarea></label><label>How would you score the week? (1–10)<input type="number" name="score" min="1" max="10" value="<?= e($current['score'] ?? '') ?>" required></label><label>Focus for next week<textarea name="focus" rows="2" maxlength="1000"><?= e($current['focus'] ?? '') ?></textarea></label><button>Save review</button></form><p class="footnote">One review per ISO week. Saving again updates this week’s entry.</p></section><section class="card"><h2>Your score over time</h2><?php $trend=array_reverse($history); ?><?= chart('line',array_column($trend,'week'),[['label'=>'Weekly score','data'=>array_column($trend,'score'),'borderColor'=>'#0071e3','tension'=>.3]],['scales'=>['y'=>['min'=>0,'max'=>10]]]) ?></section></div>
<section class="card"><h2>Recent reviews</h2><?php if (!$history): ?><p class="muted">Your first reflection starts the story.</p><?php else: foreach ($history as $review): ?><details class="review-entry"><summary><?= e($review['week']) ?> · <?= e($review['score']) ?>/10 · <?= e($review['focus']) ?></summary><dl class="lesson-detail"><dt>Wins</dt><dd><?= e($review['wins']) ?></dd><dt>What failed</dt><dd><?= e($review['fails']) ?></dd><dt>Next focus</dt><dd><?= e($review['focus']) ?></dd></dl></details><?php endforeach; endif; ?></section>
